(1605, 19, '_f_only_innovation_repeat_fields_0_name', 'innovation_repeater_name'),
(1606, 19, 'f_only_innovation_repeat_fields_0_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(1607, 19, '_f_only_innovation_repeat_fields_0_description', 'innovation_repeater_description'),
(1608, 19, 'f_only_innovation_repeat_fields_1_image', '121'),
(1609, 19, '_f_only_innovation_repeat_fields_1_image', 'innovation_repeater_image'),
(1610, 19, 'f_only_innovation_repeat_fields_1_name', 'Technology Suite'),
(1611, 19, '_f_only_innovation_repeat_fields_1_name', 'innovation_repeater_name'),
(1612, 19, 'f_only_innovation_repeat_fields_1_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(1613, 19, '_f_only_innovation_repeat_fields_1_description', 'innovation_repeater_description'),
(1614, 19, 'f_only_innovation_repeat_fields_2_image', '122'),
(1615, 19, '_f_only_innovation_repeat_fields_2_image', 'innovation_repeater_image'),
(1616, 19, 'f_only_innovation_repeat_fields_2_name', 'Marketplace Exposure '),
(1617, 19, '_f_only_innovation_repeat_fields_2_name', 'innovation_repeater_name'),
(1618, 19, 'f_only_innovation_repeat_fields_2_description', 'We offer intelligent marketing to get the maximum exposure for your property easily and effectively.\r\n\r\nOur multifaceted marketing approach begins with Costar/LoopNet. 82% of tenants and investors report they will search for their next space online, which is why LoopNet has 10 million unique visitors every month.'),
(1619, 19, '_f_only_innovation_repeat_fields_2_description', 'innovation_repeater_description'),
(1620, 19, 'f_only_innovation_repeat_fields', '3'),
(1621, 19, '_f_only_innovation_repeat_fields', 'f_only_innovation_repeater'),
(1622, 19, 'f_only_exection_title', 'Execution'),
(1623, 19, '_f_only_exection_title', 'f_only_exection_title'),
(1624, 19, 'f_only_exection_repeat_fields_0_image', '123'),
(1625, 19, '_f_only_exection_repeat_fields_0_image', 'exection_repeater_image'),
(1626, 19, 'f_only_exection_repeat_fields_0_name', 'Public Relations Impact '),
(1627, 19, '_f_only_exection_repeat_fields_0_name', 'exection_repeater_name'),
(1628, 19, 'f_only_exection_repeat_fields_0_description', 'Our public relations efforts position Gipson Real Estate as southern and central Florida\'s premier boutique commercial real estate company.\r\nIf desired by seller, Gipson will submit notable transactions to our dedicated PR firm to be published in the leading industry news sources. This exposure helps keep our brand and our agents top-of-mind with investors. This exposure also drives buyers to our website to view the exceptional properties we represent.'),
(1629, 19, '_f_only_exection_repeat_fields_0_description', 'exection_repeater_description'),
(1630, 19, 'f_only_exection_repeat_fields_1_image', '124'),
(1631, 19, '_f_only_exection_repeat_fields_1_image', 'exection_repeater_image'),
(1632, 19, 'f_only_exection_repeat_fields_1_name', 'Online Presence & Social Media '),
(1633, 19, '_f_only_exection_repeat_fields_1_name', 'exection_repeater_name'),
(1634, 19, 'f_only_exection_repeat_fields_1_description', 'Gipson invests in high-end website design and development in order to position your property in the best light. By ensuring an excellent user experience and smooth functionality, we eliminate any distractions from your quality asset.\r\n\r\nA strong social media presence has never been more valuable. Gipson values and creates exclusive, custom-designed content to encourage connections and engagement with like-minded CRE professionals, buyers, and sellers.'),
(1635, 19, '_f_only_exection_repeat_fields_1_description', 'exection_repeater_description'),
(1636, 19, 'f_only_exection_repeat_fields_2_image', '125'),
