(1730, 127, 'f_only_innovation_repeat_fields_2_name', 'Marketplace Exposure '),
(1731, 127, '_f_only_innovation_repeat_fields_2_name', 'innovation_repeater_name'),
(1732, 127, 'f_only_innovation_repeat_fields_2_description', 'We offer intelligent marketing to get the maximum exposure for your property easily and effectively.\r\n\r\nOur multifaceted marketing approach begins with Costar/LoopNet. 82% of tenants and investors report they will search for their next space online, which is why LoopNet has 10 million unique visitors every month.'),
(1733, 127, '_f_only_innovation_repeat_fields_2_description', 'innovation_repeater_description'),
