(1739, 127, '_f_only_exection_repeat_fields_0_image', 'exection_repeater_image'),
(1740, 127, 'f_only_exection_repeat_fields_0_name', 'Public Relations Impact '),
(1741, 127, '_f_only_exection_repeat_fields_0_name', 'exection_repeater_name'),
(1742, 127, 'f_only_exection_repeat_fields_0_description', 'Our public relations efforts position Gipson Real Estate as southern and central Florida\'s premier boutique commercial real estate company.\r\nIf desired by seller, Gipson will submit notable transactions to our dedicated PR firm to be published in the leading industry news sources. This exposure helps keep our brand and our agents top-of-mind with investors. This exposure also drives buyers to our website to view the exceptional properties we represent.'),
(1743, 127, '_f_only_exection_repeat_fields_0_description', 'exection_repeater_description'),
(1744, 127, 'f_only_exection_repeat_fields_1_image', '124'),
(1745, 127, '_f_only_exection_repeat_fields_1_image', 'exection_repeater_image'),
(1746, 127, 'f_only_exection_repeat_fields_1_name', 'Online Presence & Social Media '),
(1747, 127, '_f_only_exection_repeat_fields_1_name', 'exection_repeater_name'),
(1748, 127, 'f_only_exection_repeat_fields_1_description', 'Gipson invests in high-end website design and development in order to position your property in the best light. By ensuring an excellent user experience and smooth functionality, we eliminate any distractions from your quality asset.\r\n\r\nA strong social media presence has never been more valuable. Gipson values and creates exclusive, custom-designed content to encourage connections and engagement with like-minded CRE professionals, buyers, and sellers.');
