(1845, 129, '_f_only_innovation_repeat_fields_0_name', 'innovation_repeater_name'),
(1846, 129, 'f_only_innovation_repeat_fields_0_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(1847, 129, '_f_only_innovation_repeat_fields_0_description', 'innovation_repeater_description'),
