(1855, 129, '_f_only_innovation_repeat_fields_2_image', 'innovation_repeater_image'),
(1856, 129, 'f_only_innovation_repeat_fields_2_name', 'Marketplace Exposure '),
(1857, 129, '_f_only_innovation_repeat_fields_2_name', 'innovation_repeater_name'),
(1858, 129, 'f_only_innovation_repeat_fields_2_description', 'We offer intelligent marketing to get the maximum exposure for your property easily and effectively.\r\n\r\nOur multifaceted marketing approach begins with Costar/LoopNet. 82% of tenants and investors report they will search for their next space online, which is why LoopNet has 10 million unique visitors every month.'),
(1859, 129, '_f_only_innovation_repeat_fields_2_description', 'innovation_repeater_description'),
(1860, 129, 'f_only_innovation_repeat_fields', '3'),
(1861, 129, '_f_only_innovation_repeat_fields', 'f_only_innovation_repeater'),
(1862, 129, 'f_only_exection_title', 'Execution'),
(1863, 129, '_f_only_exection_title', 'f_only_exection_title'),
(1864, 129, 'f_only_exection_repeat_fields_0_image', '123'),
(1865, 129, '_f_only_exection_repeat_fields_0_image', 'exection_repeater_image'),
(1866, 129, 'f_only_exection_repeat_fields_0_name', 'Public Relations Impact '),
(1867, 129, '_f_only_exection_repeat_fields_0_name', 'exection_repeater_name'),
(1868, 129, 'f_only_exection_repeat_fields_0_description', 'Our public relations efforts position Gipson Real Estate as southern and central Florida\'s premier boutique commercial real estate company.\r\nIf desired by seller, Gipson will submit notable transactions to our dedicated PR firm to be published in the leading industry news sources. This exposure helps keep our brand and our agents top-of-mind with investors. This exposure also drives buyers to our website to view the exceptional properties we represent.'),
(1869, 129, '_f_only_exection_repeat_fields_0_description', 'exection_repeater_description'),
(1870, 129, 'f_only_exection_repeat_fields_1_image', '124'),
(1871, 129, '_f_only_exection_repeat_fields_1_image', 'exection_repeater_image'),
(1872, 129, 'f_only_exection_repeat_fields_1_name', 'Online Presence & Social Media '),
(1873, 129, '_f_only_exection_repeat_fields_1_name', 'exection_repeater_name'),
(1874, 129, 'f_only_exection_repeat_fields_1_description', 'Gipson invests in high-end website design and development in order to position your property in the best light. By ensuring an excellent user experience and smooth functionality, we eliminate any distractions from your quality asset.\r\n\r\nA strong social media presence has never been more valuable. Gipson values and creates exclusive, custom-designed content to encourage connections and engagement with like-minded CRE professionals, buyers, and sellers.'),
(1875, 129, '_f_only_exection_repeat_fields_1_description', 'exection_repeater_description'),
(1876, 129, 'f_only_exection_repeat_fields_2_image', '125'),
(1877, 129, '_f_only_exection_repeat_fields_2_image', 'exection_repeater_image'),
(1878, 129, 'f_only_exection_repeat_fields_2_name', 'Purpose-Driven Marketing Services '),
(1879, 129, '_f_only_exection_repeat_fields_2_name', 'exection_repeater_name'),
(1880, 129, 'f_only_exection_repeat_fields_2_description', 'Our Marketing Department works one-on-one with\r\nour agents and clients to design compelling marketing collateral. All listing flyers, offering memorandums, direct mailers, and case studies are entirely unique pieces catering to the needs of the client and the\r\nstrengths of the property.'),
(1881, 129, '_f_only_exection_repeat_fields_2_description', 'exection_repeater_description'),
(1882, 129, 'f_only_exection_repeat_fields', '3'),
(1883, 129, '_f_only_exection_repeat_fields', 'f_only_exection_repeater'),
