(1889, 129, '_f_only_connection_repeat_fields_0_name_bot_f', 'connection_repeater_bot_f'),
(1890, 129, 'f_only_connection_repeat_fields_0_name_bot_lin', 'In annual sales'),
(1891, 129, '_f_only_connection_repeat_fields_0_name_bot_lin', 'connection_repeater_bot_lin'),
(1892, 129, 'f_only_connection_repeat_fields_0_name', 'Unmatched Network Global Reach '),
(1893, 129, '_f_only_connection_repeat_fields_0_name', 'connection_repeater_name'),
(1894, 129, 'f_only_connection_repeat_fields_0_description', 'Gipson leverages relationships within the ONE Sotheby\'s International Realty luxury residential real estate network to connect prestigious clientele spanning the globe with the assets we represent. We manage these opportunities with extreme care to ensure impeccable, white-glove service and maintain an interconnected network to expeditiously bring you the most qualified buyers.\r\n\r\nAll Gipson property listings are shared with the ONE Sotheby\'s network via e-blasts, sales/networking events, and the ONE Sotheby\'s \"Weekly Digest\" (audience of 30,000).'),
(1895, 129, '_f_only_connection_repeat_fields_0_description', 'connection_repeater_description'),
(1896, 129, 'f_only_connection_repeat_fields', '2'),
(1897, 129, '_f_only_connection_repeat_fields', 'f_only_connection_repeater'),
