(1903, 129, '_f_only_connection_repeat_fields_1_name_bot_lin', 'connection_repeater_bot_lin'),
(1904, 129, 'f_only_connection_repeat_fields_1_name', 'Events & Sponsorships '),
(1905, 129, '_f_only_connection_repeat_fields_1_name', 'connection_repeater_name'),
(1906, 129, 'f_only_connection_repeat_fields_1_description', 'Gipson values the importance of networking. Quarterly sales meetings with ONE Sotheby\'s foster a collaborative environment in which to mingle and discuss cross-over projects and referral business. Additionally,\r\n\r\nGipson agents regularly attend industry events to expand their knowledge through invaluable initiatives and discussions impacting the industry.\r\n\r\nGipson also invests in sponsorship opportunities to keep the brand foremost for clients and colleagues.'),
(1907, 129, '_f_only_connection_repeat_fields_1_description', 'connection_repeater_description'),
