(1917, 19, '_only_repeater_0_title', 'f_ser_consul_only__repeater_title'),
(1918, 19, 'only_repeater_0_f_ser_consul_only_repeater_editor', 'Our process begins with an in-depth discussion to fully understand your objectives. Whether you are looking to buy, sell, lease, or develop commercial real estate, we tailor our approach to align with your goals.'),
(1919, 19, '_only_repeater_0_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1920, 19, 'only_repeater_0_f_ser_consul_only_repeater_img', '130'),
(1921, 19, '_only_repeater_0_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(1922, 19, 'only_repeater_1_title', 'Market Research & Property Analysis'),
(1923, 19, '_only_repeater_1_title', 'f_ser_consul_only__repeater_title'),
(1924, 19, 'only_repeater_1_f_ser_consul_only_repeater_editor', 'We conduct a detailed analysis of market conditions, trends, comparable sales, and property\r\nperformance to ensure well-informed decision-making. This research serves as the foundation\r\nfor our strategic recommendations'),
(1925, 19, '_only_repeater_1_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1926, 19, 'only_repeater_1_f_ser_consul_only_repeater_img', '131'),
(1927, 19, '_only_repeater_1_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(1928, 19, 'only_repeater_2_title', 'Customized Strategy Development'),
(1929, 19, '_only_repeater_2_title', 'f_ser_consul_only__repeater_title'),
(1930, 19, 'only_repeater_2_f_ser_consul_only_repeater_editor', 'Based on our findings, we create a personalized roadmap designed to optimize outcomes. -Whether you require aggressive marketing for a sale or a precise site selection process for an\r\nacquisition, we ensure every step is strategically planned.'),
(1931, 19, '_only_repeater_2_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1932, 19, 'only_repeater_2_f_ser_consul_only_repeater_img', '132'),
