(1934, 19, 'only_repeater_3_title', 'Expert Negotiation & Deal Structuring'),
(1935, 19, '_only_repeater_3_title', 'f_ser_consul_only__repeater_title'),
(1936, 19, 'only_repeater_3_f_ser_consul_only_repeater_editor', 'Our team of skilled negotiators advocates for your best interests, securing optimal terms that align with your financial and operational goals. We handle contract negotiations, financing\r\nstructures, and due diligence with precision.'),
(1937, 19, '_only_repeater_3_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1938, 19, 'only_repeater_3_f_ser_consul_only_repeater_img', '132'),
(1939, 19, '_only_repeater_3_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(1940, 19, 'only_repeater_4_title', 'Targeted Marketing & Outreach'),
(1941, 19, '_only_repeater_4_title', 'f_ser_consul_only__repeater_title'),
(1942, 19, 'only_repeater_4_f_ser_consul_only_repeater_editor', 'For sellers and landlords, we craft high-impact marketing campaigns utilizing professional photography, digital advertising, international investor outreach, and private client networks to\r\nattract premium buyers and tenants.'),
(1943, 19, '_only_repeater_4_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1944, 19, 'only_repeater_4_f_ser_consul_only_repeater_img', '132'),
