(1946, 19, 'only_repeater_5_title', 'Transaction Management & Closing Coordination'),
(1947, 19, '_only_repeater_5_title', 'f_ser_consul_only__repeater_title'),
(1948, 19, 'only_repeater_5_f_ser_consul_only_repeater_editor', 'We oversee every aspect of the transaction process, coordinating with legal teams, lenders, inspectors, and all involved parties to ensure a smooth, timely, and successful closing.'),
(1949, 19, '_only_repeater_5_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(1950, 19, 'only_repeater_5_f_ser_consul_only_repeater_img', '132'),
(1951, 19, '_only_repeater_5_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(1952, 19, 'only_repeater_6_title', 'Post-Transaction Support & Asset Optimization'),
(1953, 19, '_only_repeater_6_title', 'f_ser_consul_only__repeater_title'),
(1954, 19, 'only_repeater_6_f_ser_consul_only_repeater_editor', 'Our commitment to clients extends beyond deal closure. We offer continued support with asset management strategies, repositioning guidance, lease-up strategies, and long-terminvestment planning.'),
