(1997, 133, '_f_only_resources_title', 'f_only_resources_title'),
(1998, 133, 'f_only_resources_repeater_0_description', 'Gipson is a boutique brokerage with institutional quality support. Despite our institutional-level approach, we still\r\nvalue a boutique familial culture in relating to both\r\nagents and clients.'),
(1999, 133, '_f_only_resources_repeater_0_description', 'f_only_resources_repeater_description'),
(2000, 133, 'f_only_resources_repeater_0_img', '111'),
(2001, 133, '_f_only_resources_repeater_0_img', 'f_only_resources_repeater__img'),
(2002, 133, 'f_only_resources_repeater_1_description', 'Gipson takes an innovative takes an innovative approach to market intelligence and customized marketing services'),
(2003, 133, '_f_only_resources_repeater_1_description', 'f_only_resources_repeater_description'),
(2004, 133, 'f_only_resources_repeater_1_img', '113'),
(2005, 133, '_f_only_resources_repeater_1_img', 'f_only_resources_repeater__img'),
(2006, 133, 'f_only_resources_repeater_2_description', 'We execute differently.\r\nOur goal is to always keep our agents top-of-mind.'),
(2007, 133, '_f_only_resources_repeater_2_description', 'f_only_resources_repeater_description'),
(2008, 133, 'f_only_resources_repeater_2_img', '114'),
(2009, 133, '_f_only_resources_repeater_2_img', 'f_only_resources_repeater__img'),
(2010, 133, 'f_only_resources_repeater_3_description', 'Our symbiotic relationship with the ONE Sotheby’s International Realty network gives us global reach.'),
(2011, 133, '_f_only_resources_repeater_3_description', 'f_only_resources_repeater_description'),
(2012, 133, 'f_only_resources_repeater_3_img', '115'),
(2013, 133, '_f_only_resources_repeater_3_img', 'f_only_resources_repeater__img'),
(2014, 133, 'f_only_resources_repeater', '4'),
(2015, 133, '_f_only_resources_repeater', 'f_only_resources_repeater'),
(2016, 133, 'f_only_innovation_title', 'Innovation'),
(2017, 133, '_f_only_innovation_title', 'f_only_innovation_title'),
(2018, 133, 'f_only_innovation_repeat_fields_0_image', '120'),
(2019, 133, '_f_only_innovation_repeat_fields_0_image', 'innovation_repeater_image'),
(2020, 133, 'f_only_innovation_repeat_fields_0_name', 'Market Intelligence & Analytical Support'),
(2021, 133, '_f_only_innovation_repeat_fields_0_name', 'innovation_repeater_name'),
(2022, 133, 'f_only_innovation_repeat_fields_0_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(2023, 133, '_f_only_innovation_repeat_fields_0_description', 'innovation_repeater_description'),
(2024, 133, 'f_only_innovation_repeat_fields_1_image', '121'),
(2025, 133, '_f_only_innovation_repeat_fields_1_image', 'innovation_repeater_image'),
(2026, 133, 'f_only_innovation_repeat_fields_1_name', 'Technology Suite'),
(2027, 133, '_f_only_innovation_repeat_fields_1_name', 'innovation_repeater_name'),
(2028, 133, 'f_only_innovation_repeat_fields_1_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(2029, 133, '_f_only_innovation_repeat_fields_1_description', 'innovation_repeater_description'),
(2030, 133, 'f_only_innovation_repeat_fields_2_image', '122'),
(2031, 133, '_f_only_innovation_repeat_fields_2_image', 'innovation_repeater_image'),
(2032, 133, 'f_only_innovation_repeat_fields_2_name', 'Marketplace Exposure '),
(2033, 133, '_f_only_innovation_repeat_fields_2_name', 'innovation_repeater_name'),
(2034, 133, 'f_only_innovation_repeat_fields_2_description', 'We offer intelligent marketing to get the maximum exposure for your property easily and effectively.\r\n\r\nOur multifaceted marketing approach begins with Costar/LoopNet. 82% of tenants and investors report they will search for their next space online, which is why LoopNet has 10 million unique visitors every month.'),
(2035, 133, '_f_only_innovation_repeat_fields_2_description', 'innovation_repeater_description'),
(2036, 133, 'f_only_innovation_repeat_fields', '3'),
(2037, 133, '_f_only_innovation_repeat_fields', 'f_only_innovation_repeater'),
(2038, 133, 'f_only_exection_title', 'Execution'),
(2039, 133, '_f_only_exection_title', 'f_only_exection_title'),
(2040, 133, 'f_only_exection_repeat_fields_0_image', '123'),
(2041, 133, '_f_only_exection_repeat_fields_0_image', 'exection_repeater_image'),
(2042, 133, 'f_only_exection_repeat_fields_0_name', 'Public Relations Impact '),
(2043, 133, '_f_only_exection_repeat_fields_0_name', 'exection_repeater_name'),
(2044, 133, 'f_only_exection_repeat_fields_0_description', 'Our public relations efforts position Gipson Real Estate as southern and central Florida\'s premier boutique commercial real estate company.\r\nIf desired by seller, Gipson will submit notable transactions to our dedicated PR firm to be published in the leading industry news sources. This exposure helps keep our brand and our agents top-of-mind with investors. This exposure also drives buyers to our website to view the exceptional properties we represent.'),
(2045, 133, '_f_only_exection_repeat_fields_0_description', 'exection_repeater_description'),
(2046, 133, 'f_only_exection_repeat_fields_1_image', '124'),
(2047, 133, '_f_only_exection_repeat_fields_1_image', 'exection_repeater_image'),
(2048, 133, 'f_only_exection_repeat_fields_1_name', 'Online Presence & Social Media '),
(2049, 133, '_f_only_exection_repeat_fields_1_name', 'exection_repeater_name'),
(2050, 133, 'f_only_exection_repeat_fields_1_description', 'Gipson invests in high-end website design and development in order to position your property in the best light. By ensuring an excellent user experience and smooth functionality, we eliminate any distractions from your quality asset.\r\n\r\nA strong social media presence has never been more valuable. Gipson values and creates exclusive, custom-designed content to encourage connections and engagement with like-minded CRE professionals, buyers, and sellers.'),
(2051, 133, '_f_only_exection_repeat_fields_1_description', 'exection_repeater_description'),
(2052, 133, 'f_only_exection_repeat_fields_2_image', '125'),
(2053, 133, '_f_only_exection_repeat_fields_2_image', 'exection_repeater_image'),
(2054, 133, 'f_only_exection_repeat_fields_2_name', 'Purpose-Driven Marketing Services '),
(2055, 133, '_f_only_exection_repeat_fields_2_name', 'exection_repeater_name'),
(2056, 133, 'f_only_exection_repeat_fields_2_description', 'Our Marketing Department works one-on-one with\r\nour agents and clients to design compelling marketing collateral. All listing flyers, offering memorandums, direct mailers, and case studies are entirely unique pieces catering to the needs of the client and the\r\nstrengths of the property.'),
(2057, 133, '_f_only_exection_repeat_fields_2_description', 'exection_repeater_description'),
(2058, 133, 'f_only_exection_repeat_fields', '3'),
(2059, 133, '_f_only_exection_repeat_fields', 'f_only_exection_repeater'),
(2060, 133, 'f_only_connection_title', 'Global connection'),
(2061, 133, '_f_only_connection_title', 'f_only_connection_title'),
(2062, 133, 'f_only_connection_repeat_fields_0_image', '126'),
(2063, 133, '_f_only_connection_repeat_fields_0_image', 'connection_repeater_image'),
(2064, 133, 'f_only_connection_repeat_fields_0_name_bot_f', '$8.1B'),
(2065, 133, '_f_only_connection_repeat_fields_0_name_bot_f', 'connection_repeater_bot_f'),
(2066, 133, 'f_only_connection_repeat_fields_0_name_bot_lin', 'In annual sales'),
(2067, 133, '_f_only_connection_repeat_fields_0_name_bot_lin', 'connection_repeater_bot_lin'),
(2068, 133, 'f_only_connection_repeat_fields_0_name', 'Unmatched Network Global Reach '),
(2069, 133, '_f_only_connection_repeat_fields_0_name', 'connection_repeater_name'),
(2070, 133, 'f_only_connection_repeat_fields_0_description', 'Gipson leverages relationships within the ONE Sotheby\'s International Realty luxury residential real estate network to connect prestigious clientele spanning the globe with the assets we represent. We manage these opportunities with extreme care to ensure impeccable, white-glove service and maintain an interconnected network to expeditiously bring you the most qualified buyers.\r\n\r\nAll Gipson property listings are shared with the ONE Sotheby\'s network via e-blasts, sales/networking events, and the ONE Sotheby\'s \"Weekly Digest\" (audience of 30,000).'),
(2071, 133, '_f_only_connection_repeat_fields_0_description', 'connection_repeater_description'),
(2072, 133, 'f_only_connection_repeat_fields', '2'),
(2073, 133, '_f_only_connection_repeat_fields', 'f_only_connection_repeater'),
(2074, 133, 'f_only_connection_repeat_fields_1_image', '128'),
(2075, 133, '_f_only_connection_repeat_fields_1_image', 'connection_repeater_image'),
(2076, 133, 'f_only_connection_repeat_fields_1_name_bot_f', ''),
(2077, 133, '_f_only_connection_repeat_fields_1_name_bot_f', 'connection_repeater_bot_f'),
(2078, 133, 'f_only_connection_repeat_fields_1_name_bot_lin', ''),
(2079, 133, '_f_only_connection_repeat_fields_1_name_bot_lin', 'connection_repeater_bot_lin'),
(2080, 133, 'f_only_connection_repeat_fields_1_name', 'Events & Sponsorships '),
(2081, 133, '_f_only_connection_repeat_fields_1_name', 'connection_repeater_name'),
(2082, 133, 'f_only_connection_repeat_fields_1_description', 'Gipson values the importance of networking. Quarterly sales meetings with ONE Sotheby\'s foster a collaborative environment in which to mingle and discuss cross-over projects and referral business. Additionally,\r\n\r\nGipson agents regularly attend industry events to expand their knowledge through invaluable initiatives and discussions impacting the industry.\r\n\r\nGipson also invests in sponsorship opportunities to keep the brand foremost for clients and colleagues.'),
(2083, 133, '_f_only_connection_repeat_fields_1_description', 'connection_repeater_description'),
(2084, 133, 'f_ser_consul_only_title', 'A Consultative Approach'),
(2085, 133, '_f_ser_consul_only_title', 'f_ser_consul_only_title'),
(2086, 133, 'only_repeater_0_title', 'Initial Consultation & Goal Setting'),
(2087, 133, '_only_repeater_0_title', 'f_ser_consul_only__repeater_title'),
(2088, 133, 'only_repeater_0_f_ser_consul_only_repeater_editor', 'Our process begins with an in-depth discussion to fully understand your objectives. Whether you are looking to buy, sell, lease, or develop commercial real estate, we tailor our approach to align with your goals.'),
(2089, 133, '_only_repeater_0_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2090, 133, 'only_repeater_0_f_ser_consul_only_repeater_img', '130'),
(2091, 133, '_only_repeater_0_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2092, 133, 'only_repeater_1_title', 'Market Research & Property Analysis'),
(2093, 133, '_only_repeater_1_title', 'f_ser_consul_only__repeater_title'),
(2094, 133, 'only_repeater_1_f_ser_consul_only_repeater_editor', 'We conduct a detailed analysis of market conditions, trends, comparable sales, and property\r\nperformance to ensure well-informed decision-making. This research serves as the foundation\r\nfor our strategic recommendations'),
(2095, 133, '_only_repeater_1_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2096, 133, 'only_repeater_1_f_ser_consul_only_repeater_img', '131'),
(2097, 133, '_only_repeater_1_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2098, 133, 'only_repeater_2_title', 'Customized Strategy Development'),
(2099, 133, '_only_repeater_2_title', 'f_ser_consul_only__repeater_title'),
(2100, 133, 'only_repeater_2_f_ser_consul_only_repeater_editor', 'Based on our findings, we create a personalized roadmap designed to optimize outcomes. -Whether you require aggressive marketing for a sale or a precise site selection process for an\r\nacquisition, we ensure every step is strategically planned.'),
(2101, 133, '_only_repeater_2_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2102, 133, 'only_repeater_2_f_ser_consul_only_repeater_img', '132'),
(2103, 133, '_only_repeater_2_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2104, 133, 'only_repeater_3_title', 'Expert Negotiation & Deal Structuring'),
(2105, 133, '_only_repeater_3_title', 'f_ser_consul_only__repeater_title'),
(2106, 133, 'only_repeater_3_f_ser_consul_only_repeater_editor', 'Our team of skilled negotiators advocates for your best interests, securing optimal terms that align with your financial and operational goals. We handle contract negotiations, financing\r\nstructures, and due diligence with precision.'),
(2107, 133, '_only_repeater_3_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2108, 133, 'only_repeater_3_f_ser_consul_only_repeater_img', '132'),
(2109, 133, '_only_repeater_3_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2110, 133, 'only_repeater_4_title', 'Targeted Marketing & Outreach'),
(2111, 133, '_only_repeater_4_title', 'f_ser_consul_only__repeater_title'),
(2112, 133, 'only_repeater_4_f_ser_consul_only_repeater_editor', 'For sellers and landlords, we craft high-impact marketing campaigns utilizing professional photography, digital advertising, international investor outreach, and private client networks to\r\nattract premium buyers and tenants.'),
(2113, 133, '_only_repeater_4_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2114, 133, 'only_repeater_4_f_ser_consul_only_repeater_img', '132'),
(2115, 133, '_only_repeater_4_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2116, 133, 'only_repeater_5_title', 'Transaction Management & Closing Coordination'),
(2117, 133, '_only_repeater_5_title', 'f_ser_consul_only__repeater_title'),
(2118, 133, 'only_repeater_5_f_ser_consul_only_repeater_editor', 'We oversee every aspect of the transaction process, coordinating with legal teams, lenders, inspectors, and all involved parties to ensure a smooth, timely, and successful closing.'),
(2119, 133, '_only_repeater_5_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2120, 133, 'only_repeater_5_f_ser_consul_only_repeater_img', '132'),
(2121, 133, '_only_repeater_5_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2122, 133, 'only_repeater_6_title', 'Post-Transaction Support & Asset Optimization'),
(2123, 133, '_only_repeater_6_title', 'f_ser_consul_only__repeater_title'),
(2124, 133, 'only_repeater_6_f_ser_consul_only_repeater_editor', 'Our commitment to clients extends beyond deal closure. We offer continued support with asset management strategies, repositioning guidance, lease-up strategies, and long-terminvestment planning.'),
(2125, 133, '_only_repeater_6_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2126, 133, 'only_repeater_6_f_ser_consul_only_repeater_img', '132'),
(2127, 133, '_only_repeater_6_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
