(2265, 137, '_f_only_exection_repeat_fields_2_name', 'exection_repeater_name'),
(2266, 137, 'f_only_exection_repeat_fields_2_description', 'Our Marketing Department works one-on-one with\r\nour agents and clients to design compelling marketing collateral. All listing flyers, offering memorandums, direct mailers, and case studies are entirely unique pieces catering to the needs of the client and the\r\nstrengths of the property.'),
