(2290, 137, 'f_only_connection_repeat_fields_1_name', 'Events & Sponsorships '),
(2291, 137, '_f_only_connection_repeat_fields_1_name', 'connection_repeater_name'),
(2292, 137, 'f_only_connection_repeat_fields_1_description', 'Gipson values the importance of networking. Quarterly sales meetings with ONE Sotheby\'s foster a collaborative environment in which to mingle and discuss cross-over projects and referral business. Additionally,\r\n\r\nGipson agents regularly attend industry events to expand their knowledge through invaluable initiatives and discussions impacting the industry.\r\n\r\nGipson also invests in sponsorship opportunities to keep the brand foremost for clients and colleagues.'),
(2293, 137, '_f_only_connection_repeat_fields_1_description', 'connection_repeater_description'),
(2294, 137, 'f_ser_consul_only_title', 'A Consultative Approach'),
(2295, 137, '_f_ser_consul_only_title', 'f_ser_consul_only_title'),
(2296, 137, 'only_repeater_0_title', 'Initial Consultation & Goal Setting'),
