(2875, 143, '_f_only_innovation_repeat_fields_1_name', 'innovation_repeater_name'),
(2876, 143, 'f_only_innovation_repeat_fields_1_description', 'Market Intelligence Analytical Support\r\nThe Intelligence Department is constantly keeping an eye on the ever-changing real estate market. With this knowledge, our agents and clients can rest assured that our advice is guided by a comprehensive understanding of the current real estate market and are armed with the best-in-class analytical support.'),
(2877, 143, '_f_only_innovation_repeat_fields_1_description', 'innovation_repeater_description'),
(2878, 143, 'f_only_innovation_repeat_fields_2_image', '122'),
(2879, 143, '_f_only_innovation_repeat_fields_2_image', 'innovation_repeater_image'),
(2880, 143, 'f_only_innovation_repeat_fields_2_name', 'Marketplace Exposure '),
(2881, 143, '_f_only_innovation_repeat_fields_2_name', 'innovation_repeater_name'),
(2882, 143, 'f_only_innovation_repeat_fields_2_description', 'We offer intelligent marketing to get the maximum exposure for your property easily and effectively.\r\n\r\nOur multifaceted marketing approach begins with Costar/LoopNet. 82% of tenants and investors report they will search for their next space online, which is why LoopNet has 10 million unique visitors every month.'),
(2883, 143, '_f_only_innovation_repeat_fields_2_description', 'innovation_repeater_description'),
(2884, 143, 'f_only_innovation_repeat_fields', '3'),
(2885, 143, '_f_only_innovation_repeat_fields', 'f_only_innovation_repeater'),
(2886, 143, 'f_only_exection_title', 'Execution'),
(2887, 143, '_f_only_exection_title', 'f_only_exection_title'),
(2888, 143, 'f_only_exection_repeat_fields_0_image', '123'),
(2889, 143, '_f_only_exection_repeat_fields_0_image', 'exection_repeater_image'),
(2890, 143, 'f_only_exection_repeat_fields_0_name', 'Public Relations Impact '),
(2891, 143, '_f_only_exection_repeat_fields_0_name', 'exection_repeater_name'),
(2892, 143, 'f_only_exection_repeat_fields_0_description', 'Our public relations efforts position Gipson Real Estate as southern and central Florida\'s premier boutique commercial real estate company.\r\nIf desired by seller, Gipson will submit notable transactions to our dedicated PR firm to be published in the leading industry news sources. This exposure helps keep our brand and our agents top-of-mind with investors. This exposure also drives buyers to our website to view the exceptional properties we represent.'),
(2893, 143, '_f_only_exection_repeat_fields_0_description', 'exection_repeater_description'),
(2894, 143, 'f_only_exection_repeat_fields_1_image', '124'),
(2895, 143, '_f_only_exection_repeat_fields_1_image', 'exection_repeater_image'),
(2896, 143, 'f_only_exection_repeat_fields_1_name', 'Online Presence & Social Media '),
(2897, 143, '_f_only_exection_repeat_fields_1_name', 'exection_repeater_name'),
(2898, 143, 'f_only_exection_repeat_fields_1_description', 'Gipson invests in high-end website design and development in order to position your property in the best light. By ensuring an excellent user experience and smooth functionality, we eliminate any distractions from your quality asset.\r\n\r\nA strong social media presence has never been more valuable. Gipson values and creates exclusive, custom-designed content to encourage connections and engagement with like-minded CRE professionals, buyers, and sellers.'),
(2899, 143, '_f_only_exection_repeat_fields_1_description', 'exection_repeater_description'),
(2900, 143, 'f_only_exection_repeat_fields_2_image', '125'),
(2901, 143, '_f_only_exection_repeat_fields_2_image', 'exection_repeater_image'),
(2902, 143, 'f_only_exection_repeat_fields_2_name', 'Purpose-Driven Marketing Services '),
(2903, 143, '_f_only_exection_repeat_fields_2_name', 'exection_repeater_name'),
(2904, 143, 'f_only_exection_repeat_fields_2_description', 'Our Marketing Department works one-on-one with\r\nour agents and clients to design compelling marketing collateral. All listing flyers, offering memorandums, direct mailers, and case studies are entirely unique pieces catering to the needs of the client and the\r\nstrengths of the property.'),
(2905, 143, '_f_only_exection_repeat_fields_2_description', 'exection_repeater_description'),
(2906, 143, 'f_only_exection_repeat_fields', '3'),
(2907, 143, '_f_only_exection_repeat_fields', 'f_only_exection_repeater'),
(2908, 143, 'f_only_connection_title', 'Global connection'),
(2909, 143, '_f_only_connection_title', 'f_only_connection_title'),
(2910, 143, 'f_only_connection_repeat_fields_0_image', '126'),
(2911, 143, '_f_only_connection_repeat_fields_0_image', 'connection_repeater_image'),
(2912, 143, 'f_only_connection_repeat_fields_0_name_bot_f', '$8.1B'),
(2913, 143, '_f_only_connection_repeat_fields_0_name_bot_f', 'connection_repeater_bot_f'),
(2914, 143, 'f_only_connection_repeat_fields_0_name_bot_lin', 'In annual sales'),
(2915, 143, '_f_only_connection_repeat_fields_0_name_bot_lin', 'connection_repeater_bot_lin'),
(2916, 143, 'f_only_connection_repeat_fields_0_name', 'Unmatched Network Global Reach '),
(2917, 143, '_f_only_connection_repeat_fields_0_name', 'connection_repeater_name'),
(2918, 143, 'f_only_connection_repeat_fields_0_description', 'Gipson leverages relationships within the ONE Sotheby\'s International Realty luxury residential real estate network to connect prestigious clientele spanning the globe with the assets we represent. We manage these opportunities with extreme care to ensure impeccable, white-glove service and maintain an interconnected network to expeditiously bring you the most qualified buyers.\r\n\r\nAll Gipson property listings are shared with the ONE Sotheby\'s network via e-blasts, sales/networking events, and the ONE Sotheby\'s \"Weekly Digest\" (audience of 30,000).'),
(2919, 143, '_f_only_connection_repeat_fields_0_description', 'connection_repeater_description'),
(2920, 143, 'f_only_connection_repeat_fields', '2'),
(2921, 143, '_f_only_connection_repeat_fields', 'f_only_connection_repeater'),
(2922, 143, 'f_only_connection_repeat_fields_1_image', '128'),
(2923, 143, '_f_only_connection_repeat_fields_1_image', 'connection_repeater_image'),
