(2925, 143, '_f_only_connection_repeat_fields_1_name_bot_f', 'connection_repeater_bot_f'),
(2926, 143, 'f_only_connection_repeat_fields_1_name_bot_lin', ''),
(2927, 143, '_f_only_connection_repeat_fields_1_name_bot_lin', 'connection_repeater_bot_lin'),
(2928, 143, 'f_only_connection_repeat_fields_1_name', 'Events & Sponsorships '),
(2929, 143, '_f_only_connection_repeat_fields_1_name', 'connection_repeater_name'),
(2930, 143, 'f_only_connection_repeat_fields_1_description', 'Gipson values the importance of networking. Quarterly sales meetings with ONE Sotheby\'s foster a collaborative environment in which to mingle and discuss cross-over projects and referral business. Additionally,\r\n\r\nGipson agents regularly attend industry events to expand their knowledge through invaluable initiatives and discussions impacting the industry.\r\n\r\nGipson also invests in sponsorship opportunities to keep the brand foremost for clients and colleagues.'),
(2931, 143, '_f_only_connection_repeat_fields_1_description', 'connection_repeater_description'),
(2932, 143, 'f_ser_consul_only_title', 'A Consultative Approach'),
(2933, 143, '_f_ser_consul_only_title', 'f_ser_consul_only_title'),
(2934, 143, 'only_repeater_0_title', 'Initial Consultation & Goal Setting'),
(2935, 143, '_only_repeater_0_title', 'f_ser_consul_only__repeater_title'),
(2936, 143, 'only_repeater_0_f_ser_consul_only_repeater_editor', 'Our process begins with an in-depth discussion to fully understand your objectives. Whether you are looking to buy, sell, lease, or develop commercial real estate, we tailor our approach to align with your goals.'),
(2937, 143, '_only_repeater_0_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2938, 143, 'only_repeater_0_f_ser_consul_only_repeater_img', '130'),
(2939, 143, '_only_repeater_0_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2940, 143, 'only_repeater_1_title', 'Market Research & Property Analysis'),
(2941, 143, '_only_repeater_1_title', 'f_ser_consul_only__repeater_title'),
(2942, 143, 'only_repeater_1_f_ser_consul_only_repeater_editor', 'We conduct a detailed analysis of market conditions, trends, comparable sales, and property\r\nperformance to ensure well-informed decision-making. This research serves as the foundation\r\nfor our strategic recommendations'),
(2943, 143, '_only_repeater_1_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2944, 143, 'only_repeater_1_f_ser_consul_only_repeater_img', '131'),
(2945, 143, '_only_repeater_1_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2946, 143, 'only_repeater_2_title', 'Customized Strategy Development'),
(2947, 143, '_only_repeater_2_title', 'f_ser_consul_only__repeater_title'),
(2948, 143, 'only_repeater_2_f_ser_consul_only_repeater_editor', 'Based on our findings, we create a personalized roadmap designed to optimize outcomes. -Whether you require aggressive marketing for a sale or a precise site selection process for an\r\nacquisition, we ensure every step is strategically planned.'),
(2949, 143, '_only_repeater_2_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2950, 143, 'only_repeater_2_f_ser_consul_only_repeater_img', '132'),
(2951, 143, '_only_repeater_2_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2952, 143, 'only_repeater_3_title', 'Expert Negotiation & Deal Structuring'),
(2953, 143, '_only_repeater_3_title', 'f_ser_consul_only__repeater_title'),
(2954, 143, 'only_repeater_3_f_ser_consul_only_repeater_editor', 'Our team of skilled negotiators advocates for your best interests, securing optimal terms that align with your financial and operational goals. We handle contract negotiations, financing\r\nstructures, and due diligence with precision.'),
(2955, 143, '_only_repeater_3_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2956, 143, 'only_repeater_3_f_ser_consul_only_repeater_img', '132'),
(2957, 143, '_only_repeater_3_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2958, 143, 'only_repeater_4_title', 'Targeted Marketing & Outreach'),
(2959, 143, '_only_repeater_4_title', 'f_ser_consul_only__repeater_title'),
(2960, 143, 'only_repeater_4_f_ser_consul_only_repeater_editor', 'For sellers and landlords, we craft high-impact marketing campaigns utilizing professional photography, digital advertising, international investor outreach, and private client networks to\r\nattract premium buyers and tenants.'),
(2961, 143, '_only_repeater_4_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2962, 143, 'only_repeater_4_f_ser_consul_only_repeater_img', '132'),
(2963, 143, '_only_repeater_4_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2964, 143, 'only_repeater_5_title', 'Transaction Management & Closing Coordination'),
(2965, 143, '_only_repeater_5_title', 'f_ser_consul_only__repeater_title'),
(2966, 143, 'only_repeater_5_f_ser_consul_only_repeater_editor', 'We oversee every aspect of the transaction process, coordinating with legal teams, lenders, inspectors, and all involved parties to ensure a smooth, timely, and successful closing.'),
(2967, 143, '_only_repeater_5_f_ser_consul_only_repeater_editor', 'f_ser_consul_only_repeater_text'),
(2968, 143, 'only_repeater_5_f_ser_consul_only_repeater_img', '132'),
(2969, 143, '_only_repeater_5_f_ser_consul_only_repeater_img', 'f_ser_consul_only_repeater_img'),
(2970, 143, 'only_repeater_6_title', 'Post-Transaction Support & Asset Optimization'),
(2971, 143, '_only_repeater_6_title', 'f_ser_consul_only__repeater_title'),
(2972, 143, 'only_repeater_6_f_ser_consul_only_repeater_editor', 'Our commitment to clients extends beyond deal closure. We offer continued support with asset management strategies, repositioning guidance, lease-up strategies, and long-terminvestment planning.'),
